        private void BtnToggleWidget_Click(object s, RoutedEventArgs e)
        {
            try { AppLogger.Info($"Widget toggle clicked — sender={(s as FrameworkElement)?.Name ?? s?.GetType().Name ?? "null"}"); }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }

            bool wasVisible = false;
            try { wasVisible = _compactWidget != null && _compactWidget.IsVisible; }
            catch (System.Exception __ignored) { SMDWin.Services.AppLogger.Swallowed(__ignored); /* window already destroyed */ }

            SetWidgetVisible(!wasVisible);
        }

        private void SetWidgetVisible(bool show)
        {
            if (_compactWidget != null)
            {
                try { _compactWidget.Close(); } catch (Exception ex) { AppLogger.Debug($"Widget close: {ex.Message}"); }
                _compactWidget = null;
            }

            if (show)
            {
                try
                {
                    _compactWidget = new SMDWin.Views.CompactWidgetWindow();
                    _compactWidget.CancelShutdown = CancelShutdownFromWidget;
                    _compactWidget.StyleChanged   = UpdateWidgetStyleButtons; // style changed from the widget menu
                    _compactWidget.Closed += (_, _) =>
                    {
                        _compactWidget = null;
                        UpdateWidgetCaptionIndicator();
                        // If the window was closed directly (the X in the corner), not only from the toggle, keep the setting in sync —
                        // otherwise it would reappear on restart.
                        if (SettingsService.Current.WidgetEnabled)
                        {
                            SettingsService.Current.WidgetEnabled = false;
                            SettingsService.Save();
                            if (ChkWidgetEnabled != null) ChkWidgetEnabled.IsChecked = false;
                        }
                    };
                    _compactWidget.Show();
                    _compactWidget.MoveToDefaultPosition();
                    // The next tick does a full read, it does not wait for the current page's interval
                    _lastFullSensorReadUtc = DateTime.MinValue;

                    try
                    {
                        float ramPctNow = _cachedTotalRamMB > 0 && _cachedAvailRamMB >= 0
                            ? Math.Clamp(100f * (1f - _cachedAvailRamMB / _cachedTotalRamMB), 0f, 100f)
                            : -1f;
                        int didxNow = (_chartIdx > 0 ? _chartIdx - 1 : 0) % ChartMaxPoints;
                        _compactWidget.PushData(
                            cpuPct: _cachedCpuPct, gpuPct: _cachedGpuPct, ramPct: ramPctNow,
                            netUp: _emaNetUp, netDown: _emaNetDown,
                            diskRead: _dashDiskRead[didxNow], diskWrite: _dashDiskWrite[didxNow],
                            cpuTemp: _lastTempSnap?.CpuTemp, gpuTemp: _lastTempSnap?.GpuTemp,
                            cpuFreqMHz: _lastTempSnap?.CpuFreqMHz);
                    }
                    catch (Exception ex) { AppLogger.Debug($"Widget instant snapshot: {ex.Message}"); }
                }
                catch (Exception ex)
                {
                    AppLogger.Warning(ex, "MainWindow.ToggleWidget");
                    _compactWidget = null;
                }
            }

            SettingsService.Current.WidgetEnabled = _compactWidget != null;
            SettingsService.Save();
            if (ChkWidgetEnabled != null) ChkWidgetEnabled.IsChecked = SettingsService.Current.WidgetEnabled;
            UpdateWidgetCaptionIndicator();
        }

        /// <summary>The "Show sensors in Widget" checkbox in Settings — the same action as the title bar button, just started
        /// from the card, next to Tray Sensors.</summary>
        internal void ChkWidgetEnabled_Changed(object s, RoutedEventArgs e)
        {
            SetWidgetVisible(ChkWidgetEnabled?.IsChecked == true);
            UpdateWidgetTrayPanels();
        }

        private void UpdateWidgetCaptionIndicator()
        {
            try
            {
                bool on = _compactWidget != null && _compactWidget.IsVisible;
                UpdateWidgetTrayPanels();
                if (FindName("WidgetCaptionDot") is System.Windows.Shapes.Ellipse dot)
                    dot.Visibility = on ? Visibility.Visible : Visibility.Collapsed;
                if (FindName("WidgetTitleDot") is System.Windows.Shapes.Ellipse dot2)
                    dot2.Visibility = on ? Visibility.Visible : Visibility.Collapsed;
                if (FindName("BtnCaptionWidget") is Button bw)
                    bw.ToolTip = on ? "Live Widget: ON — click pentru inchidere"
                                    : "Live Widget — mini fereastra always-on-top cu statistici";
                if (FindName("BtnTitleWidget") is Button bw2)
                    bw2.ToolTip = on ? "Live Widget: ON — click pentru inchidere"
                                     : "Live Widget — mini fereastra always-on-top cu statistici";
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }
        }

        internal void ResetChart_Click(object s, RoutedEventArgs e)
        {
            _qCpu.Clear(); _qGpu.Clear(); _qRam.Clear();
            _qDiskR.Clear(); _qDiskW.Clear();
            _qNetDown.Clear(); _qNetUp.Clear(); _qPing.Clear();
            _qCpuTemp.Clear(); _qGpuTemp.Clear();
            _emaNetDown = 0f; _emaNetUp = 0f; _emaPingSmooth = 0f;
            _rolNetIdx = 0; _rolNetCnt = 0;
            _rolDiskIdx = 0; _rolDiskCnt = 0;
            _diskWarmupTicks = 0;
            if (_dynMaxCache != null) _dynMaxCache.Clear();

            _cpuMin = null; _cpuMax = null; _gpuMin = null; _gpuMax = null;
            _diskTempMinMax.Clear();
            UpdateDiskTempRows();
            if (FindName("TxtStCpuMinMax") is TextBlock stCpuMmR) stCpuMmR.Text = "";
            if (FindName("TxtStGpuMinMax") is TextBlock stGpuMmR) stGpuMmR.Text = "";
            if (FindName("TxtCpuTempMin")  is TextBlock ctMinR)  ctMinR.Text  = "—";
            if (FindName("TxtCpuTempMax")  is TextBlock ctMaxR)  ctMaxR.Text  = "—";
            if (FindName("TxtCpuTempAvg")  is TextBlock ctAvgR)  ctAvgR.Text  = "—";
            if (FindName("TxtCpuTempMinS") is TextBlock ctMinS)  ctMinS.Text  = "—";
            if (FindName("TxtCpuTempMaxS") is TextBlock ctMaxS)  ctMaxS.Text  = "—";
            if (FindName("TxtCpuTempAvgS") is TextBlock ctAvgS)  ctAvgS.Text  = "—";
            if (FindName("TxtGpuTempMinS") is TextBlock gtMinS)  gtMinS.Text  = "—";
            if (FindName("TxtGpuTempMaxS") is TextBlock gtMaxS)  gtMaxS.Text  = "—";

            _cpuFreqMin = float.MaxValue; _cpuFreqMax = 0f; _cpuFreqSum = 0f;
            _cpuLoadMin = float.MaxValue; _cpuLoadMax = 0f; _cpuLoadSum = 0f; _cpuLoadCnt = 0;
            _cpuPowerMin = float.MaxValue; _cpuPowerMax = float.MinValue;
            _cpuVCoreMin = float.MaxValue; _cpuVCoreMax = float.MinValue; _cpuVCoreSum = 0f; _cpuVCoreCnt = 0;
            _gpuTempMin = float.MaxValue; _gpuTempMax = 0f; _gpuTempSum = 0f; _gpuTempCnt = 0;
            _gpuLoadMin = float.MaxValue; _gpuLoadMax = 0f; _gpuLoadSum = 0f; _gpuLoadCnt = 0; _gpuPwMin = float.MaxValue; _gpuPwMax = 0f;
            _gpuFreqMin = float.MaxValue; _gpuFreqMax = float.MinValue;
            _gpuMemFreqMin = float.MaxValue; _gpuMemFreqMax = float.MinValue;
            _gpuPowerMin = float.MaxValue; _gpuPowerMax = float.MinValue;
            _gpuVramMin = null; _gpuVramMax = null;
            _ramLoadMin = float.MaxValue; _ramLoadMax = 0f; _ramLoadSum = 0f; _ramLoadCnt = 0;
            _coreTempsSessMin = float.MaxValue; _coreTempsSessMax = float.MinValue; _coreTempsSessSum = 0f; _coreTempsSessCnt = 0;

            foreach (var name in new[] {
                "TxtCpuFreqMin", "TxtCpuFreqMax", "TxtCpuLoadMin", "TxtCpuLoadMax",
                "TxtCpuLoadMin_c", "TxtCpuLoadMax_c", "TxtCpuPowerMax", "TxtCpuVCoreMin", "TxtCpuVCoreMax",
                "TxtGpuTempMin", "TxtGpuTempMax", "TxtGpuTempMinChart", "TxtGpuTempMaxChart",
                "TxtGpuLoadMin", "TxtGpuLoadMax", "TxtGpuClockMax", "TxtGpuMemClockMin", "TxtGpuMemClockMax",
                "TxtGpuVramMin", "TxtGpuVramMax", "TxtRamLoadMin", "TxtRamLoadMax",
                "TxtCoreTempsMin", "TxtCoreTempsMax", "TxtCoreTempsAvg",
            })
                if (FindName(name) is TextBlock tb) tb.Text = "—";

            _renderDirty = true;
        }

        // ── the widget style (Pill / Gauges / Minimal) ─────────────────────────
        internal void WidgetStyle_Click(object sender, RoutedEventArgs e)
        {
            if (_settingsUiLoading || sender is not FrameworkElement fe || fe.Tag is not string style) return;
            if (sender is System.Windows.Controls.RadioButton rbs && rbs.IsChecked != true) return;
            SettingsService.Current.WidgetStyle = style;
            SettingsService.Save();
            try { _compactWidget?.ApplyMetrics(); }
            catch (Exception ex) { AppLogger.Debug($"WidgetStyle_Click: {ex.Message}"); }
            UpdateWidgetStyleButtons();
        }

        private void UpdateWidgetStyleButtons()
        {
            string cur = SettingsService.Current.WidgetStyle ?? "Gauges";
            foreach (var name in new[] { "BtnWidgetStylePill", "BtnWidgetStyleGauges", "BtnWidgetStyleMinimal" })
                if (FindName(name) is Wpf.Ui.Controls.Button b)
                    SetTabButtonActive(b, (b.Tag as string) == cur);
            CheckSilently(cur == "Pill" ? "RbWidgetStylePill" : cur == "Minimal" ? "RbWidgetStyleMinimal" : "RbWidgetStyleGauges");
        }

        internal void ChkTraySensors_Changed(object s, RoutedEventArgs e)
        {
            SettingsService.Current.TraySensorsEnabled = ChkTraySensors?.IsChecked == true;
            SettingsService.Save();
            try { RebuildTraySensorIcons(); }
            catch (Exception ex) { AppLogger.Debug($"ChkTraySensors_Changed: {ex.Message}"); }
            BuildMetricsMatrix();   // the tray options appear / disappear with the switch
        }

        internal void WidgetAlertOnly_Changed(object s, RoutedEventArgs e)
